zone.script:
if flag("vented") == 1 {
  let squad = alive_count("player");
  let here = zone_count("lift", "player");
  if squad > 0 && here >= squad { message("Into the core lift. Straight down to the Heart."); win(); }
  else { message(here + " of " + squad + " here - everyone still alive has to make it."); }
} else { message("The lift won't move while the coolant's flowing - open the three valves first."); }

tile.script:
if flag("valve0") == 0 {
  set_flag("valve0", 1);
  set_flag("valves", flag("valves") + 1);
  message("Valve open. Coolant roars away into the dark. (" + flag("valves") + " of 3)");
  zone_label("valve0", "VALVE (open)");
  if flag("valves") >= 3 {
    set_flag("vented", 1);
    message("All three valves open: the Heart is starting to overheat. VESPER: 'Stop. STOP.'");
    objective("Get the whole squad to the core lift (east)");
  } else { objective("Open the three coolant valves (" + flag("valves") + " of 3)"); }
}

