mission.script:
set_flag("valves", 0); set_flag("vented", 0);
message("The coolant works. Steam vents blast across the walkways every few turns.");
objective("Open the three coolant valves (0 of 3)");

// Steam: scalding blasts on the walkways.
if round % 3 == 0 {
  let v = [[16, 15], [31, 15], [24, 16], [38, 14], [17, 17], [30, 17]];
  let p = v[rand(0, v.len() - 1)];
  ignite(p[0], p[1], 1.5, 1);
  message("Steam blasts across the walkway!");
}

let squad = alive_count("player");
if flag("vented") == 1 && squad > 0 && zone_count("lift", "player") >= squad {
  message("Into the core lift. Straight down to the Heart.");
  win();
}
